[trp_sod_strategy_advisor, "sod_sa_war_room_minifactions_black_army", [], "The Black Army values discipline, contracts, and clean chains of command. Those are virtues when roads need securing fast. But mercenary loyalty is rented, not rooted. Pay them for work you can measure; do not build the heart of your realm from soldiers who salute the purse first.", "sod_sa_war_room_minifactions_answer", []],
